-- Diagramas de cancha (animables) para los ejercicios.

alter table public.exercises add column diagram jsonb check (
  diagram is null or (
    jsonb_typeof(diagram) = 'object'
    and jsonb_typeof(diagram->'items') = 'array'
    and jsonb_typeof(diagram->'moves') = 'array'
    and jsonb_array_length(diagram->'items') <= 60
    and jsonb_array_length(diagram->'moves') <= 80
  )
);

